package com.collectionlogprogress;

import java.util.Collection;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;

final class CollectionPage
{
    private final int[][] itemIdsBySlot;

    CollectionPage(int[] itemIds)
    {
        itemIdsBySlot = new int[itemIds.length][];
        for (int itemIndex = 0; itemIndex < itemIds.length; itemIndex++)
        {
            int itemId = itemIds[itemIndex];
            // Normalize bag slots only: generic mappings can group unrelated reward crates.
            if (itemId == ItemID.COAL_BAG || itemId == ItemID.GEM_BAG)
            {
                itemId = ItemVariationMapping.map(itemId);
            }
            Collection<Integer> variations = ItemVariationMapping.getVariations(itemId);
            int[] slotItemIds = new int[variations.size()];
            int variationIndex = 0;
            for (int variation : variations)
            {
                slotItemIds[variationIndex++] = variation;
            }
            itemIdsBySlot[itemIndex] = slotItemIds;
        }
    }

    int getTotal()
    {
        return itemIdsBySlot.length;
    }

    int countObtained(Set<Integer> obtainedItems)
    {
        int count = 0;
        for (int[] slotItemIds : itemIdsBySlot)
        {
            for (int itemId : slotItemIds)
            {
                if (obtainedItems.contains(itemId))
                {
                    count++;
                    break;
                }
            }
        }
        return count;
    }
}

package com.collectionlogprogress;

import java.util.List;

final class CompletionSort
{
    private CompletionSort()
    {
    }

    static void sort(
        List<Integer> pageIndexes,
        int[] percentages,
        String[] pageNames,
        boolean reverse
    )
    {
        pageIndexes.sort((leftIndex, rightIndex) -> compare(
            percentages[leftIndex],
            pageNames[leftIndex],
            percentages[rightIndex],
            pageNames[rightIndex],
            reverse
        ));
    }

    private static int compare(
        int leftPercentage,
        String leftName,
        int rightPercentage,
        String rightName,
        boolean reverse
    )
    {
        int percentageComparison = reverse
            ? Integer.compare(leftPercentage, rightPercentage)
            : Integer.compare(rightPercentage, leftPercentage);
        if (percentageComparison != 0)
        {
            return percentageComparison;
        }

        String safeLeftName = leftName == null ? "" : leftName;
        String safeRightName = rightName == null ? "" : rightName;
        int nameComparison = String.CASE_INSENSITIVE_ORDER.compare(safeLeftName, safeRightName);
        return nameComparison != 0
            ? nameComparison
            : safeLeftName.compareTo(safeRightName);
    }
}

package com.collectionlogprogress;

enum CompletionOrder
{
    DEFAULT(false, false),
    DESCENDING(true, false),
    ASCENDING(true, true);

    private final boolean sorted;
    private final boolean reversed;

    CompletionOrder(boolean sorted, boolean reversed)
    {
        this.sorted = sorted;
        this.reversed = reversed;
    }

    static CompletionOrder fromConfig(boolean sorted, boolean reversed)
    {
        if (!sorted)
        {
            return DEFAULT;
        }
        return reversed ? ASCENDING : DESCENDING;
    }

    CompletionOrder next()
    {
        switch (this)
        {
            case DEFAULT:
                return DESCENDING;
            case DESCENDING:
                return ASCENDING;
            case ASCENDING:
            default:
                return DEFAULT;
        }
    }

    boolean isSorted()
    {
        return sorted;
    }

    boolean isReversed()
    {
        return reversed;
    }
}

package com.collectionlogprogress;

enum ProgressState
{
    UNSTARTED,
    PARTIAL,
    COMPLETED;

    static ProgressState from(int obtained, int total)
    {
        if (total > 0 && obtained >= total)
        {
            return COMPLETED;
        }
        if (obtained <= 0)
        {
            return UNSTARTED;
        }
        return PARTIAL;
    }
}

