{
    String GROUP = "collection-log-progress";
    String SORT_BY_COMPLETION_KEY = "sortByCompletion";
    String REVERSE_COMPLETION_SORT_KEY = "reverseCompletionSort";

    @ConfigSection(
        name = "Sidebar",
        description = "Collection Log page-list appearance",
